import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int s = sc.nextInt();
        int h = s / 3600;
        int m = (s % 3600) / 60;
        int sec = s % 60;
        System.out.println(String.format("%d:%02d:%02d", h, m, sec));
    }
}
